mapper.sql:
FROM "lines" AS "l" INNER JOIN "daiya_revisions" AS "dr" ON "dr"."del_flag" = 0 AND "dr"."rosen_id" = "l"."rosen_id" INNER JOIN "agencies" AS "ag" ON "ag"."del_flag" = 0 AND "ag"."available_flag" = 1 AND "ag"."business_corp_id" = "l"."business_corp_id" WHERE "l"."del_flag" = 0 AND "l"."available_flag" = 1
AND "l"."rosen_id" = #{rosenId}
AND "l"."business_corp_id" = #{businessCorpId}
AND "lr"."line_route_id" = #{lineRouteId}
AND "dr"."daiya_revision_id" = #{daiyaRevisionId}
AND "dr"."service_end_date" >= CAST(#{serviceStartDate} AS DATE)
AND "dr"."service_start_date" <= CAST(#{serviceEndDate} AS DATE)
AND EXISTS ( SELECT 1 FROM "line_routes" AS "lr" WHERE "lr"."del_flag" = 0 AND "lr"."available_flag" = 1 AND "lr"."rosen_id" = "l"."rosen_id" AND "lr"."line_detail_service_division" = #{lineDetailServiceDivision} )

mapper.select:
SELECT "bs"."bus_service_id" , "bs"."bus_service_name" , "bs"."bus_service_trip_id" FROM "lines" AS "l" INNER JOIN "agencies" AS "a" ON "a"."del_flag" = 0 AND "a"."available_flag" = 1 AND "a"."business_corp_id" = "l"."business_corp_id" INNER JOIN "daiya_revisions" AS "dr" ON "dr"."del_flag" = 0 AND "dr"."rosen_id" = "l"."rosen_id" INNER JOIN "bus_services" AS "bs" ON "bs"."del_flag" = 0 AND "bs"."daiya_revision_id" = "dr"."daiya_revision_id" INNER JOIN ( SELECT "bd1"."bus_service_id" , MIN("bd1"."bus_stop_departure_time") AS "bus_stop_departure_time" FROM "bus_daiyas" AS "bd1" WHERE "bd1"."del_flag" = 0 GROUP BY "bd1"."bus_service_id" ) AS "bd" ON "bd"."bus_service_id" = "bs"."bus_service_id" LEFT JOIN "offices" AS "o" ON "o"."del_flag" = 0 AND "o"."available_flag" = 1 AND "o"."office_id" = "bs"."office_id" LEFT JOIN "operating_companies" AS "oc" ON "oc"."del_flag" = 0 AND "oc"."available_flag" = 1 AND "oc"."operating_company_id" = "o"."operating_company_id" WHERE "l"."del_flag" = 0 AND "l"."available_flag" = 1 AND "l"."business_corp_id" = #{businessCorpId} AND EXISTS ( SELECT 1 FROM "daily_bus_daiyas" AS "dbd" WHERE "dbd"."del_flag" = 0 AND "dbd"."bus_service_id" = "bs"."bus_service_id"
AND "dbd"."sales_cancel_flg" = #{salesCancelFlg}
AND "dbd"."service_date" >= CAST(#{serviceStartDate} AS date)
AND "dbd"."service_date" <= CAST(#{serviceEndDate} AS date)
)
AND "oc"."operating_company_id" = #{operatingCompanyId}
AND "l"."rosen_id" = #{rosenId}
AND "bd"."bus_stop_departure_time" >= #{busStopDepartureTimeStart}
AND "bd"."bus_stop_departure_time" <= #{busStopDepartureTimeEnd}

SELECT "o"."office_id" AS "officeId" , "o"."name" AS "officeName" FROM "operating_companies" AS "oc" INNER JOIN "offices" AS "o" ON "o"."operating_company_id" = "oc"."operating_company_id" AND "o"."available_flag" = 1 AND "o"."del_flag" = 0 WHERE "oc"."available_flag" = 1 AND "oc"."del_flag" = 0 AND "oc"."business_corp_id" = #{businessCorpId}
AND "oc"."operating_company_id" = #{operatingCompanyId}
ORDER BY "oc"."operating_company_id" ASC , "o"."office_id" ASC

SELECT "lbs"."rosen_bus_stop_id" AS "rosenBusStopId" , "lbs"."sequence_no" AS "sequenceNo" , "bs"."bus_stop_name" AS "busStopName" , "lbs"."ride_alight_division" AS "rideAlightDivision" FROM "line_bus_stops" AS "lbs" INNER JOIN "bus_stops" AS "bs" ON "lbs"."bus_stop_id" = "bs"."bus_stop_id" AND "bs"."del_flag" = 0 AND "bs"."available_flag" = 1 AND "lbs"."del_flag" = 0 AND "lbs"."rosen_id" = #{rosenId}
ORDER BY "lbs"."sequence_no" ASC
ORDER BY "lbs"."sequence_no" DESC
